const doc=document.documentElement;
const scene=document.createElement('div');scene.className='spatial-scene';scene.setAttribute('aria-hidden','true');const canvas=document.createElement('canvas');scene.append(canvas);document.body.prepend(scene);
const main=document.querySelector('main');if(main){main.id||='workspace';const skip=document.createElement('a');skip.className='space-skip';skip.href='#'+main.id;skip.textContent='Skip to workspace';document.body.prepend(skip);}
const links=[['./#regression-lab','Regression','Reproduce & verify'],['./#stress-lab','Stress lab','Boundaries & invariants'],['copilot.html','QA Copilot','Risks & test plans'],['api-lab.html','API Lab','Requests & authentication'],['testing-workbench.html','Workbench','Stories & sessions'],['human-testing.html#hist','HIST','Human intelligence'],['human-testing.html#agile','Agile testing','Sprint evidence'],['human-testing.html#readiness','Release review','Gaps & decisions']];
const nav=document.createElement('nav');nav.className='spatial-nav';nav.setAttribute('aria-label','ReleaseRadar workspaces');for(const [href,label]of links){const a=document.createElement('a');a.href=href;a.textContent=label;nav.append(a);}main?.prepend(nav);function navState(){nav.querySelectorAll('a').forEach(a=>{const url=new URL(a.href),path=location.pathname==='/'?'/index.html':location.pathname,target=url.pathname==='/'?'/index.html':url.pathname;const active=target===path&&(!url.hash||url.hash===location.hash||(!location.hash&&['#hist','#regression-lab'].includes(url.hash)));if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}navState();addEventListener('hashchange',navState);
const actions=document.querySelector('.top-actions')||document.querySelector('.bar')||nav;
const control=document.getElementById('background-motion')||document.createElement('button');control.id='background-motion';control.type='button';control.className='spatial-toggle';if(!control.isConnected)actions.append(control);
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let on=true;try{on=localStorage.getItem('rr-spatial-motion')!=='off';}catch{}let frame=0,last=0,time=0;const ctx=canvas.getContext('2d');let width=innerWidth,height=innerHeight;const stars=Array.from({length:100},(_,i)=>({x:((i*73.13)%100)/100,y:((i*37.91)%100)/100,z:.25+(i%7)/9}));let px=0,py=0;
function resize(){width=innerWidth;height=innerHeight;const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=width*dpr;canvas.height=height*dpr;ctx?.setTransform(dpr,0,0,dpr,0,0);draw();}
function draw(){if(!ctx)return;ctx.clearRect(0,0,width,height);for(const s of stars){const x=(s.x*width+time*s.z*.003+px*s.z*18+width)%width,y=(s.y*height+py*s.z*12+height)%height;ctx.fillStyle=`rgba(184,212,223,${.13+s.z*.4})`;ctx.beginPath();ctx.arc(x,y,.5+s.z*.6,0,Math.PI*2);ctx.fill();}}
function active(){return on&&!reduced.matches&&!document.hidden;}
function tick(now){frame=0;if(!active())return;if(now-last>32){time+=Math.min(now-last,50);last=now;draw();}frame=requestAnimationFrame(tick);}
function update(){const enabled=on&&!reduced.matches;doc.dataset.spatialMotion=enabled?'on':'off';doc.classList.toggle('motion-off',!enabled);control.textContent=reduced.matches?'Reduced motion':'Motion: '+(on?'on':'off');control.setAttribute('aria-label',reduced.matches?'Motion disabled by your system preference':on?'Pause background motion':'Enable background motion');control.setAttribute('aria-pressed',String(enabled));control.disabled=reduced.matches;cancelAnimationFrame(frame);frame=0;draw();if(active())frame=requestAnimationFrame(tick);}
control.onclick=()=>{on=!on;try{localStorage.setItem('rr-spatial-motion',on?'on':'off');}catch{}update();};reduced.addEventListener('change',update);document.addEventListener('visibilitychange',update);addEventListener('resize',resize,{passive:true});addEventListener('pointermove',e=>{if(!active()||e.pointerType!=='mouse')return;px=e.clientX/width-.5;py=e.clientY/height-.5;doc.style.setProperty('--orbit-x',px);doc.style.setProperty('--orbit-y',py);},{passive:true});
const progress=document.createElement('div');progress.className='space-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);let scrollQueued=false;function scrollPaint(){scrollQueued=false;doc.style.setProperty('--page-progress',Math.min(1,scrollY/Math.max(1,doc.scrollHeight-innerHeight)));if(active())doc.style.setProperty('--launch-scroll',Math.min(1,scrollY/700));}addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(scrollPaint);}},{passive:true});resize();update();scrollPaint();
