const search=document.createElement('button');search.type='button';search.className='space-search';search.innerHTML='Find a tool <kbd>Ctrl K</kbd>';actions.append(search);const dialog=document.createElement('dialog');dialog.className='space-command';dialog.setAttribute('aria-labelledby','command-title');dialog.innerHTML='<header><h2 id="command-title">Where next?</h2><button type="button" aria-label="Close tool search">Close</button></header><label for="tool-search">Search your workspaces</label><input id="tool-search" type="search" placeholder="Try API, Agile, evidence…" autocomplete="off"><div class="space-results"></div><p class="fine" role="status" id="tool-count"></p>';document.body.append(dialog);const input=dialog.querySelector('input'),results=dialog.querySelector('.space-results');function render(){results.replaceChildren();for(const [href,label,description]of links.filter(row=>row.join(' ').toLowerCase().includes(input.value.toLowerCase().trim()))){const a=document.createElement('a');a.href=href;const title=document.createElement('span'),small=document.createElement('small');title.textContent=label;small.textContent=description;a.append(title,small);a.addEventListener('click',()=>dialog.close());results.append(a);}document.getElementById('tool-count').textContent=results.children.length?`${results.children.length} tools · Tab to choose · Esc to close`:'No tools found. Try a shorter search.';}
search.onclick=()=>{input.value='';render();dialog.showModal();input.focus();};dialog.querySelector('button').onclick=()=>dialog.close();input.oninput=render;input.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();results.querySelector('a')?.focus();}if(e.key==='Enter'&&results.children.length===1)results.firstElementChild.click();};addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(dialog.open)dialog.close();else search.click();}});
